SELECT analytics_order_facts.category, SUM(analytics_order_facts.contribution_margin) AS contribution_margin FROM analytics_order_facts WHERE analytics_order_facts.year = 2023 AND analytics_order_facts.month = 2 AND analytics_order_facts.region = 'West' AND analytics_order_facts.channel = 'retail' AND analytics_order_facts.customer_segment = 'consumer' GROUP BY analytics_order_facts.category ORDER BY contribution_margin DESC, analytics_order_facts.category ASC LIMIT 4
